rss.channel:
Hugo News
Recent news about Hugo, a static site generator written in Go, optimized for speed and designed for flexibility.
{{ page.permalink }}
Hugo 0.149.0-DEV
{{ site.language_code or site.lang }}
{%- if site.copyright %}
  {{ site.copyright }}
{%- endif %}
{%- if page.output_formats.rss %}
  {%- set feed = page.output_formats.rss %}

{%- endif %}
{%- set limit = site.config.services.rss.limit %}
{%- if limit <= 0 %}
  {%- set limit = 999 %}
{%- endif %}
{%- set news = get_page(path="/news") %}
{%- if news %}
  {%- set pages = news.pages | by_publish_date | reverse %}
  {%- set pages = pages[:limit] %}
{%- else %}
  {{- log_error(message="The list.rss.xml layout was unable to find the 'news' page.") }}
  {%- set pages = [] %}
{%- endif %}
{%- set newest = pages | first %}
{% if newest %}{{ newest.publish_date | date(format="%a, %d %b %Y %H:%M:%S %z") }}{% endif %}
{%- for p in pages %}


    {{ p.title }}
    {{ p.params.permalink or p.permalink }}
    {{ p.publish_date | date(format="%a, %d %b %Y %H:%M:%S %z") }}
    {{ p.params.permalink or p.permalink }}
    {{ p.summary | xml_escape }}

{%- endfor %}
